import SwiftUI

/// The one object every screen reads. The Shell area owns creating the `Node` (see android CoreService.kt) and
/// sets `node` once the vault is unlocked. Other areas only read it; they never create or close it.
/// `Node` etc. are the UniFFI types in ios/build/generated/p2pcore.swift (regenerated by ios/scripts/build_core.sh).
///
/// The rest is android P2pApp's observable state that is not another area's: the Shell's `ShellCore`
/// (Screens/Shell/ShellCore.swift) writes it on the main actor; every other area only reads it, or writes the hooks marked
/// as such. Contacts, blocks and contact requests live in the People area's `PeopleModel` (injected as an environment
/// object next to this one); the fields below mirror them for areas that only hold an `AppEnv`.
@MainActor
final class AppEnv: ObservableObject {
    @Published var node: Node?

    /// The core's network status (`onStatus`); nil until the node reported once.
    @Published var status: NodeStatus?
    @Published var lockState: LockState = .noIdentity
    @Published var hasIdentity = false
    /// The selected account's DID (changes when the user switches); nil with no account.
    @Published var accountDid: String?
    /// Bumped when the core says the accounts changed (`AccountEvents.onAccountsChanged`: unread counts, background
    /// accounts): the account lists re-read `accounts()`.
    @Published var accountsTick = 0
    /// The call log, newest first. Re-read on every call end (the core writes it before `Ended` fires).
    @Published var history: [CallRecord] = []
    /// Group calls this device was in or missed, newest first (the core's group call log; local to this device).
    @Published var groupLog: [GroupCallRecord] = []
    @Published var availability = Availability(available: true, until: nil)
    /// Set while a new account is being created/restored next to the existing ones.
    @Published var adding: ShellAdding?
    /// Set (to the account's name) when another device removed the account from this phone; the screen clears it.
    @Published var unlinked: String?
    /// The 1:1 conversations (chat list), mirrored from the Chat area's `ChatSource`.
    @Published var chats: [Chat] = []

    /// Mirrors of the People area's `PeopleModel` (read-only here).
    @Published var contacts: [Contact] = []
    @Published var blocks = Blocks()
    @Published var requestsIn: [ContactRequest] = []
    @Published var requestsOut: [ContactRequest] = []

    /// A message hit the user opened in Search, for the GROUPS area (the Chat area gets it as `ConversationView.searchHit`):
    /// read it, scroll to the message, highlight it and clear it.
    @Published var searchJump: MessageHit?

    /// The node lifecycle (android P2pApp + CoreService). Created by the Shell's root on first appearance.
    var core: ShellCore?
}
